-- agent-history squashed baseline schema (schema_version 1).
-- Generated by pg_dump --schema-only from the catalogue schema and numbered migrations.
-- Apply once to a database without table ah.meta; bundled migrations are already present.
-- Do not edit by hand.

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_extension WHERE extname = 'vector') THEN CREATE EXTENSION vector; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_extension WHERE extname = 'pg_search') THEN CREATE EXTENSION pg_search; END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_namespace WHERE nspname = 'ah') THEN CREATE SCHEMA ah; END IF; END $$;

CREATE TABLE ah.artifact (
    id bigint NOT NULL,
    agent text NOT NULL,
    event_uid text NOT NULL,
    session_id bigint NOT NULL,
    turn_key text,
    call_uid text,
    ts timestamp with time zone NOT NULL,
    kind text NOT NULL,
    action text NOT NULL,
    path text NOT NULL,
    display_name text,
    evidence_type text NOT NULL,
    source_id bigint NOT NULL,
    byte_offset bigint NOT NULL
);

CREATE SEQUENCE ah.artifact_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE ah.artifact_id_seq OWNED BY ah.artifact.id;

