CREATE TABLE ah.change_log (
    seq bigint NOT NULL,
    refresh_id bigint NOT NULL,
    agent text NOT NULL,
    session_uid text NOT NULL,
    agent_id text DEFAULT ''::text NOT NULL,
    kind text NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT change_log_kind_check CHECK ((kind = ANY (ARRAY['content'::text, 'orchestration'::text, 'rebuild'::text])))
);

COMMENT ON TABLE ah.change_log IS 'Monotonic per-refresh change feed keyed by session natural key; resume from the last seen seq. Never truncated by rebuild (a rebuild writes one kind=rebuild row with session_uid ''*''). Pruned after 90 days.';

CREATE SEQUENCE ah.change_log_seq_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE ah.change_log_seq_seq OWNED BY ah.change_log.seq;

CREATE TABLE ah.chunk (
    id bigint NOT NULL,
    message_id bigint,
    summary_id bigint,
    session_id bigint,
    namespace text NOT NULL,
    ts timestamp with time zone NOT NULL,
    chunk_no smallint NOT NULL,
    char_start integer NOT NULL,
    char_end integer NOT NULL,
    source_sha256 text NOT NULL,
    model text NOT NULL,
    input_sha256 text NOT NULL,
    tool_call_id bigint,
    tool_op_id bigint,
    CONSTRAINT chunk_one_source CHECK ((num_nonnulls(message_id, summary_id, tool_call_id, tool_op_id) = 1))
);

COMMENT ON COLUMN ah.chunk.source_sha256 IS 'message.content_sha256, session_summary.journal_revision_id, or sha256 hex of tool_call/tool_op.error_excerpt';

