CREATE TABLE ah.llm_call (
    id bigint NOT NULL,
    agent text NOT NULL,
    response_id text NOT NULL,
    session_id bigint NOT NULL,
    turn_key text,
    ts timestamp with time zone NOT NULL,
    model text,
    request_id text,
    stop_reason text,
    input_uncached bigint,
    cache_read bigint,
    cache_write_5m bigint,
    cache_write_1h bigint,
    output bigint,
    reasoning bigint,
    context_tokens bigint GENERATED ALWAYS AS ((((COALESCE(input_uncached, (0)::bigint) + COALESCE(cache_read, (0)::bigint)) + COALESCE(cache_write_5m, (0)::bigint)) + COALESCE(cache_write_1h, (0)::bigint))) STORED,
    context_window bigint,
    web_search_requests integer,
    web_fetch_requests integer,
    service_tier text,
    speed text,
    effort text,
    is_api_error boolean DEFAULT false NOT NULL,
    error_kind text,
    api_error_status integer,
    is_sidechain boolean DEFAULT false NOT NULL,
    line_count integer,
    source_id bigint NOT NULL,
    byte_offset bigint NOT NULL
)
WITH (autovacuum_vacuum_scale_factor='0.02');

