CREATE TABLE ah.message (
    id bigint NOT NULL,
    agent text NOT NULL,
    event_uid text NOT NULL,
    session_id bigint NOT NULL,
    namespace text NOT NULL,
    profile text NOT NULL,
    turn_key text,
    ts timestamp with time zone NOT NULL,
    role text NOT NULL,
    message_class text NOT NULL,
    model text,
    is_sidechain boolean DEFAULT false NOT NULL,
    text text NOT NULL,
    content_sha256 text NOT NULL,
    source_id bigint NOT NULL,
    byte_offset bigint NOT NULL,
    byte_length integer NOT NULL,
    line_number bigint,
    prompt_origin text,
    detail jsonb,
    text_sha256 text,
    seq bigint,
    raw_record_origin text,
    CONSTRAINT message_message_class_check CHECK ((message_class = ANY (ARRAY['human_prompt'::text, 'queued_prompt'::text, 'assistant_text'::text, 'subagent_brief'::text, 'subagent_report'::text, 'compaction_summary'::text, 'task_notification_summary'::text, 'reasoning'::text, 'system_prompt'::text, 'system_reminder'::text, 'context_injection'::text, 'hook_output'::text, 'command_expansion'::text, 'skill_body'::text, 'local_command_output'::text, 'agent_message'::text, 'interrupt_marker'::text]))),
    CONSTRAINT message_prompt_origin_check CHECK ((prompt_origin = ANY (ARRAY['typed'::text, 'pasted'::text, 'slash_command'::text, 'skill'::text, 'hook'::text, 'local_command'::text, 'launch_message'::text, 'compaction_continuation'::text, 'agent_message'::text, 'interrupt'::text, 'other'::text]))),
    CONSTRAINT message_role_check CHECK ((role = ANY (ARRAY['user'::text, 'assistant'::text, 'system'::text])))
)
WITH (autovacuum_vacuum_scale_factor='0', autovacuum_vacuum_threshold='100000');

COMMENT ON COLUMN ah.message.content_sha256 IS 'sha256 hex of message.text exactly as stored (UTF-8 bytes, after the loader drops NUL characters). Equal to text_sha256.';

COMMENT ON COLUMN ah.message.text_sha256 IS 'sha256 hex of message.text as stored (UTF-8 bytes): encode(sha256(convert_to(text, ''UTF8'')), ''hex'').';

COMMENT ON COLUMN ah.message.seq IS 'Per-session order across message, tool_call, tool_op (tool_io shares its call/op seq). Deterministic from source position, so stable across rebuild; new rows append.';

