    session_uid text,
    session_agent_id text
);

CREATE TABLE ah.source_file (
    id bigint NOT NULL,
    rel_path text NOT NULL,
    namespace text NOT NULL,
    agent text NOT NULL,
    profile text NOT NULL,
    machine text,
    file_role text NOT NULL,
    logical_uid text,
    tier text NOT NULL,
    available_hot boolean DEFAULT false NOT NULL,
    available_cold boolean DEFAULT false NOT NULL,
    size_bytes bigint DEFAULT 0 NOT NULL,
    mtime_ns bigint DEFAULT 0 NOT NULL,
    indexed_offset bigint DEFAULT 0 NOT NULL,
    line_count bigint DEFAULT 0 NOT NULL,
    checkpoint_start bigint DEFAULT 0 NOT NULL,
    checkpoint_sha256 text,
    head_sha256 text,
    parser_version text DEFAULT ''::text NOT NULL,
    parser_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    rewrite_count integer DEFAULT 0 NOT NULL,
    indexed_at timestamp with time zone,
    CONSTRAINT source_file_agent_check CHECK ((agent = ANY (ARRAY['claude'::text, 'codex'::text, 'pi'::text]))),
    CONSTRAINT source_file_file_role_check CHECK ((file_role = ANY (ARRAY['main'::text, 'subagent'::text, 'workflow_agent'::text, 'workflow_journal'::text, 'pi_artifact'::text]))),
    CONSTRAINT source_file_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'indexed'::text, 'partial'::text, 'unavailable'::text, 'error'::text]))),
    CONSTRAINT source_file_tier_check CHECK ((tier = ANY (ARRAY['hot'::text, 'cold'::text])))
);

