    requested_type text,
    requested_type_source text,
    requested_model text,
    resolved_model text,
    reasoning_effort text,
    background boolean,
    fork_scope text,
    isolation text,
    name text,
    description text,
    launch_status text,
    completion_status text,
    completed_at timestamp with time zone,
    reported_tokens bigint,
    reported_tool_uses integer,
    reported_duration_ms bigint,
    workflow_id text,
    source_id bigint NOT NULL,
    byte_offset bigint NOT NULL,
    CONSTRAINT subagent_spawn_requested_type_source_check CHECK ((requested_type_source = ANY (ARRAY['explicit'::text, 'default'::text])))
);

