CREATE TABLE ah.tool_call (
    id bigint NOT NULL,
    agent text NOT NULL,
    call_uid text NOT NULL,
    session_id bigint NOT NULL,
    turn_key text,
    response_id text,
    tool_name text NOT NULL,
    tool_family text,
    mcp_server text,
    mcp_tool text,
    codex_namespace text,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    duration_ms integer,
    input_bytes integer,
    output_bytes integer,
    persisted_output_bytes bigint,
    outcome text,
    is_error boolean,
    exit_code integer,
    denial_kind text,
    interrupted boolean,
    timed_out boolean,
    background boolean,
    attribution_skill text,
    attribution_plugin text,
    meta jsonb,
    source_id bigint NOT NULL,
    byte_offset bigint NOT NULL,
    error_class text,
    error_excerpt text,
    seq bigint,
    CONSTRAINT tool_call_outcome_check CHECK ((outcome = ANY (ARRAY['ok'::text, 'error'::text, 'denied'::text, 'interrupted'::text, 'timeout'::text, 'no_result'::text])))
)
WITH (autovacuum_vacuum_scale_factor='0.02');

