    id bigint NOT NULL,
    agent text NOT NULL,
    io_uid text NOT NULL,
    session_id bigint NOT NULL,
    namespace text NOT NULL,
    profile text NOT NULL,
    kind text NOT NULL,
    tool_name text,
    call_uid text,
    item_uid text,
    turn_key text,
    ts timestamp with time zone NOT NULL,
    output_at timestamp with time zone,
    input_text text,
    input_bytes integer,
    input_sha256 text,
    input_truncated boolean,
    output_text text,
    output_bytes integer,
    output_sha256 text,
    output_truncated boolean,
    stdout_text text,
    stdout_bytes integer,
    stdout_sha256 text,
    stderr_text text,
    stderr_bytes integer,
    stderr_sha256 text,
    result_json text,
    result_bytes integer,
    result_sha256 text,
    output_parts jsonb,
    seq bigint,
    source_id bigint NOT NULL,
    byte_offset bigint NOT NULL,
    output_byte_offset bigint,
    CONSTRAINT tool_io_kind_check CHECK ((kind = ANY (ARRAY['call'::text, 'op'::text])))
)
WITH (autovacuum_vacuum_scale_factor='0.02');

COMMENT ON TABLE ah.tool_io IS 'Full tool input and output (Claude tool_use/tool_result, Codex calls and executed ops). *_bytes are UTF-8 octet lengths and *_sha256 the sha256 hex of each stored text column. Binary parts are metadata only.';

